/* ============================================
   CIRCULAR BUTTON (ICON BUTTON)
   Round button with a single icon
   ============================================ */

.ds-circular-button {
  /* Layout */
  display: inline-flex;
  align-items: center;
  justify-content: center;

  /* Size — default */
  width: 40px;
  height: 40px;

  /* Shape */
  border-radius: var(--radius-pill); /* 999px — perfect circle */

  /* Transitions */
  transition: background-color var(--motion-duration-base) var(--motion-ease-standard), border-color var(--motion-duration-base) var(--motion-ease-standard), opacity var(--motion-duration-base) var(--motion-ease-standard);

  /* Reset */
  cursor: pointer;
  border: none;
  padding: 0;
  text-decoration: none;
  color: inherit;
}

/* ============================================
   SIZE — DEFAULT
   ============================================ */

.ds-circular-button--default {
  width: 40px;
  height: 40px;
}

/* ============================================
   SIZE — COMPACT
   ============================================ */

.ds-circular-button--compact {
  width: 32px;
  height: 32px;
}

.ds-circular-button--compact .ds-circular-button__icon {
  --icon-size: var(--icon-size-500);
}

/* ============================================
   ICON
   ============================================ */

.ds-circular-button__icon {
  flex-shrink: 0;
  --icon-size: var(--icon-size-600);
  line-height: 1;
}

/* ============================================
   PRIMARY VARIANT (SOLID)
   ============================================ */

.ds-circular-button--primary {
  background-color: var(--color-action-primary-bg);
  border: none;
}

.ds-circular-button--primary .ds-circular-button__icon {
  color: var(--color-action-primary-text);
}

.ds-circular-button--primary.ds-circular-button--hover {
  background-color: var(--color-action-primary-bg-hover);
}

.ds-circular-button--primary.ds-circular-button--hover .ds-circular-button__icon {
  color: var(--color-action-primary-text-active);
}

.ds-circular-button--primary.ds-circular-button--active {
  background-color: var(--color-action-primary-bg-active);
}

.ds-circular-button--primary.ds-circular-button--active .ds-circular-button__icon {
  color: var(--color-action-primary-text-active);
}

.ds-circular-button--primary.ds-circular-button--disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* Interactive hover/active */
.ds-circular-button--primary:not(.ds-circular-button--disabled):hover {
  background-color: var(--color-action-primary-bg-hover);
}

.ds-circular-button--primary:not(.ds-circular-button--disabled):hover .ds-circular-button__icon {
  color: var(--color-action-primary-text-active);
}

.ds-circular-button--primary:not(.ds-circular-button--disabled):active {
  background-color: var(--color-action-primary-bg-active);
}

.ds-circular-button--primary:not(.ds-circular-button--disabled):active .ds-circular-button__icon {
  color: var(--color-action-primary-text-active);
}

/* ============================================
   SECONDARY VARIANT (OUTLINED)
   ============================================ */

.ds-circular-button--secondary {
  border: var(--border-025) solid var(--color-action-primary-border);
  background-color: transparent;
}

.ds-circular-button--secondary .ds-circular-button__icon {
  color: var(--color-action-icon-default);
}

.ds-circular-button--secondary.ds-circular-button--hover {
  background-color: var(--color-action-primary-bg-hover);
}

.ds-circular-button--secondary.ds-circular-button--hover .ds-circular-button__icon {
  color: var(--color-action-icon-active);
}

.ds-circular-button--secondary.ds-circular-button--active {
  background-color: var(--color-action-primary-bg-active);
}

.ds-circular-button--secondary.ds-circular-button--active .ds-circular-button__icon {
  color: var(--color-action-icon-active);
}

.ds-circular-button--secondary.ds-circular-button--disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* Interactive hover/active */
.ds-circular-button--secondary:not(.ds-circular-button--disabled):hover {
  background-color: var(--color-action-primary-bg-hover);
}

.ds-circular-button--secondary:not(.ds-circular-button--disabled):hover .ds-circular-button__icon {
  color: var(--color-action-icon-active);
}

.ds-circular-button--secondary:not(.ds-circular-button--disabled):active {
  background-color: var(--color-action-primary-bg-active);
}

.ds-circular-button--secondary:not(.ds-circular-button--disabled):active .ds-circular-button__icon {
  color: var(--color-action-icon-active);
}

/* ============================================
   TERTIARY VARIANT (PASSIVE / GHOST)
   ============================================ */

.ds-circular-button--tertiary {
  background-color: var(--color-action-passive-bg);
  border: none;
}

.ds-circular-button--tertiary .ds-circular-button__icon {
  color: var(--color-icon-primary);
}

.ds-circular-button--tertiary.ds-circular-button--hover {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-circular-button--tertiary.ds-circular-button--active {
  background-color: var(--color-action-passive-bg-active);
}

.ds-circular-button--tertiary.ds-circular-button--disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* Interactive hover/active */
.ds-circular-button--tertiary:not(.ds-circular-button--disabled):hover {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-circular-button--tertiary:not(.ds-circular-button--disabled):active {
  background-color: var(--color-action-passive-bg-active);
}

/* ============================================
   NEUTRAL VARIANT (SOLID GREY)
   Filled like primary but in the neutral greys —
   unlike tertiary, the background is always shown.
   ============================================ */

.ds-circular-button--neutral {
  background-color: var(--color-action-neutral-bg);
  border: none;
}

.ds-circular-button--neutral .ds-circular-button__icon {
  color: var(--color-action-neutral-text);
}

.ds-circular-button--neutral.ds-circular-button--hover {
  background-color: var(--color-action-neutral-bg-hover);
}

.ds-circular-button--neutral.ds-circular-button--active {
  background-color: var(--color-action-neutral-bg-active);
}

.ds-circular-button--neutral.ds-circular-button--disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* Interactive hover/active */
.ds-circular-button--neutral:not(.ds-circular-button--disabled):hover {
  background-color: var(--color-action-neutral-bg-hover);
}

.ds-circular-button--neutral:not(.ds-circular-button--disabled):active {
  background-color: var(--color-action-neutral-bg-active);
}

/* ============================================
   LOADING
   Keeps the variant's full-colour appearance (no disabled dim);
   the spinner replaces the icon and inherits its colour.
   ============================================ */

.ds-circular-button--loading {
  cursor: progress;
  pointer-events: none;
}

/* The spinner is a box, not a glyph: left inline, it sits on the text
   baseline and the strut's descender pushes it ~1px above the button's
   centre. Flex centres it geometrically. */
.ds-circular-button--loading .ds-circular-button__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

/* ============================================
   FOCUS
   ============================================ */

.ds-circular-button:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
}

// No 'use client' directive: CircularButton defines no hooks or handlers of its
// own — consumers' event props fall through — so Server Components can render it.
// The default Tooltip wrapper is the client island; like MessageActions, the
// button itself stays server-renderable.
import React from 'react';
import { Spinner } from '../Spinner/Spinner';
import { Tooltip } from '../Tooltip/Tooltip';
import './CircularButton.css';
import '../../fonts/material-symbols.css';

/** Props owned by CircularButton itself — everything else falls through to the DOM node. */
type CircularButtonOwnProps = {
  /** The icon — Material Symbol name (string) or custom element (ReactNode) */
  icon: string | React.ReactNode;
  /** Visual treatment */
  variant?: 'primary' | 'secondary' | 'tertiary' | 'neutral';
  /**
   * Legacy alias for `variant`.
   *
   * @deprecated Use `variant` instead.
   */
  priority?: 'primary' | 'secondary' | 'tertiary';
  /** Whether the button is disabled */
  disabled?: boolean;
  /**
   * Documentation-only interaction state.
   *
   * @deprecated Use `disabled` for the disabled state.
   *
   * Documentation-only affordance for rendering a *static* interaction state in
   * Storybook and the showcase site. Real hover/active styling comes from CSS
   * pseudo-classes and needs no prop — for docs, prefer
   * `className="ds-circular-button--hover"`.
   */
  state?: 'default' | 'hover' | 'active' | 'disabled';
  /** Button size */
  size?: 'default' | 'compact';
  /**
   * Shows a spinner in place of the icon and blocks interaction while an
   * async action runs. Keeps the variant's full-colour appearance (unlike
   * the disabled state) and sets `aria-busy` on the rendered element.
   */
  loading?: boolean;
  /** Accessible label — required, because the button has no visible text */
  ariaLabel: string;
  /**
   * The hover/focus tooltip. An icon-only control names itself: by default
   * the button wears a Tooltip carrying `ariaLabel`. Pass a string to show
   * different wording, or `false` to opt out — for a host that labels the
   * control another way, or one that owns the button's box directly
   * (SplitButton's trigger stretches to its sibling segment, which the
   * tooltip wrapper would block).
   */
  tooltip?: string | false;
  /** Which side the tooltip opens on. */
  tooltipPosition?: 'top' | 'bottom' | 'left' | 'right';
  /** Optional href — renders as <a> instead of <button> */
  href?: string;
  /** Optional target attribute for links */
  target?: string;
  /** Optional rel attribute for links */
  rel?: string;
  /** Additional CSS classes */
  className?: string;
};

export interface CircularButtonProps
  extends CircularButtonOwnProps,
    Omit<React.ComponentPropsWithoutRef<'button'>, keyof CircularButtonOwnProps | 'type'> {}

/**
 * Circular icon button component.
 * A round button containing a single icon, available in
 * primary, secondary, tertiary and neutral variants with default and compact sizes.
 *
 * Renders a `<button>`, or an `<a>` when `href` is supplied. Forwards a ref to
 * whichever element it renders, and spreads unrecognised props onto it.
 */
export const CircularButton = React.forwardRef<
  HTMLButtonElement | HTMLAnchorElement,
  CircularButtonProps
>(
  (
    {
      icon,
      variant,
      priority,
      disabled,
      state,
      size = 'default',
      loading,
      ariaLabel,
      tooltip,
      tooltipPosition = 'top',
      href,
      target,
      rel,
      className = '',
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-circular-button';

    // `priority` is the deprecated spelling of `variant`; `variant` wins when both are set.
    const resolvedVariant = variant ?? priority ?? 'primary';
    // `disabled` is the real prop; `state="disabled"` is the deprecated path.
    const isDisabled = disabled ?? state === 'disabled';
    // Keep the state modifier class so the disabled styling applies either way.
    const resolvedState = state ?? (isDisabled ? 'disabled' : 'default');
    const isLoading = Boolean(loading);

    const classes = [
      baseClass,
      `${baseClass}--${resolvedVariant}`,
      `${baseClass}--${resolvedState}`,
      `${baseClass}--${size}`,
      isLoading && `${baseClass}--loading`,
      className,
    ]
      .filter(Boolean)
      .join(' ');

    const children = isLoading ? (
      <span className={`${baseClass}__icon`} aria-hidden="true">
        <Spinner size={size === 'compact' ? 'sm' : 'md'} variant="inherit" />
      </span>
    ) : (
      <span className={`${baseClass}__icon${typeof icon === 'string' ? ' material-symbols-rounded' : ''}`} aria-hidden="true">
        {icon}
      </span>
    );

    // A loading link renders the button branch so interaction is truly blocked.
    const control =
      href && !isDisabled && !isLoading ? (
        <a
          {...(rest as React.ComponentPropsWithoutRef<'a'>)}
          ref={ref as React.Ref<HTMLAnchorElement>}
          className={classes}
          href={href}
          target={target}
          rel={rel}
          aria-label={ariaLabel}
        >
          {children}
        </a>
      ) : (
        <button
          {...rest}
          ref={ref as React.Ref<HTMLButtonElement>}
          type="button"
          className={classes}
          disabled={isDisabled || isLoading}
          aria-busy={isLoading || undefined}
          aria-label={ariaLabel}
        >
          {children}
        </button>
      );

    // Self-labelling: the tooltip repeats the accessible name unless the
    // caller overrides the wording or opts out.
    const tooltipContent = tooltip === false ? null : (tooltip ?? ariaLabel);
    if (!tooltipContent) return control;
    return (
      <Tooltip content={tooltipContent} position={tooltipPosition}>
        {control}
      </Tooltip>
    );
  },
);

CircularButton.displayName = 'CircularButton';
